-- =====================================================================================
-- Extra mock dispensing (Aug 24 - Oct 23 2026) for the Predictive Medicine Demand forecast.
-- Adds 617 clinic_visits (VMOCK-*) with one consultation_dispensation each (DMOCK-*) on top of
-- seed_jan2025_oct2026_dispensing.sql. Every medicine gets dispensations in the last 30 days; most
-- Tablet medicines (Biogesic, Dolfenal, Kremil-S, Bonamine, Medicol, Catapres) plus Band-Aid are weighted
-- so their 30-day demand is higher than current stock. Serc, Imodium, Bioflu, Salonpas and the liquids stay
-- below stock for contrast. No Capsule medicine exists in the medicines table yet.
-- Quantities respect each medicine's dispense unit / dispense limit. Mon-Fri only, medicines are only
-- dispensed for complaints they are linked to in medicine_indications. Stock is NOT changed.
-- Safe to re-run: deletes its own VMOCK-% / DMOCK-% rows first.
-- =====================================================================================

USE ClinicManagementSystem;
SET time_zone = '+08:00';
SET SQL_SAFE_UPDATES = 0;
START TRANSACTION;

DELETE FROM consultation_dispensation WHERE consultation_dispense_id LIKE 'DMOCK-%';
DELETE FROM clinic_visits WHERE visit_id LIKE 'VMOCK-%';









COMMIT;
